using UnityEngine;
using System.Collections.Generic;

public class BejeweledGame : MonoBehaviour
{
    public GameObject[] gemstones;
    public int rows = 8;
    public int cols = 8;
    public float speed = 1f;

    private List<Gemstone> gemstoneList = new List<Gemstone>();
    private Gemstone[,] grid;
    private int score = 0;

    void Start()
    {
        InitializeGame();
    }

    void InitializeGame()
    {
        grid = new Gemstone[rows, cols];
        for (int i = 0; i < rows; i++)
        {
            for (int j = 0; j < cols; j++)
            {
                Gemstone gemstone = (GameObject)Instantiate(gemstones[Random.Range(0, gemstones.Length)], new Vector3(i, j, 0), Quaternion.identity);
                gemstone.transform.parent = transform;
                grid[i, j] = gemstone.GetComponent<Gemstone>();
                gemstoneList.Add(grid[i, j]);
            }
        }
    }

    void Update()
    {
        CheckForCollisions();
        MoveGemstones();
    }

    void CheckForCollisions()
    {
        int rowsMatched = 0;
        int colsMatched = 0;
        for (int i = 0; i < rows; i++)
        {
            for (int j = 0; j < cols; j++)
            {
                if (grid[i, j].color == grid[i, j + 1].color && j < cols - 1)
                {
                    colsMatched++;
                }

                if (grid[i, j].color == grid[i + 1, j].color && i < rows - 1)
                {
                    rowsMatched++;
                }
            }
        }

        if (rowsMatched > 0 || colsMatched > 0)
        {
            DeleteMatchedGemstones();
            score += rowsMatched * 10 + colsMatched * 20;
        }
    }

    void DeleteMatchedGemstones()
    {
        foreach (Gemstone gemstone in gemstoneList)
        {
            if (gemstone.color == GemstoneColor.Green || gemstone.color == GemstoneColor.Purple)
            {
                Destroy(gemstone.gameObject);
                gemstoneList.Remove(gemstone);
            }
        }
    }

    void MoveGemstones()
    {
        foreach (Gemstone gemstone in gemstoneList)
        {
            gemstone.UpdatePosition(new Vector2Int((int)gemstone.transform.position.x, (int)gemstone.transform.position.y));
        }
    }
}
```
